def validar(x, n, a):
    flag = False
    visibles = 1

    for i in range(2, n+1):
        if(x[i] == 1):
            visibles += 1

    if(visibles == a[1]):
        flag = True

        for i in range(1, n):
            if(x[i] == 1 and x[i+1] == 1):
                visibles -= 1
            elif(x[i] == 0 and x[i+1] == 0):
                visibles += 1

            if(a[i+1] != visibles):
                flag = False
                break

    return flag

