#include <bits/stdc++.h>
using namespace std;
using ll = long long;
using vll = vector <ll>;

const ll MAXN = 3E5+16, B = 800;
vll adj[MAXN];
vll cols[MAXN], comps[MAXN];
ll comp_col[MAXN];
ll timer = 1, cur = 1;
ll last[MAXN];
bool active[MAXN];
ll curMap[MAXN];
int preProc[MAXN/B+16][MAXN];

void dfs1 (ll u, ll par) {
    vll th(cols[u].size()), th2(cols[u].size());
    comps[u].resize(cols[u].size());
    for (ll i = 0; i < cols[u].size(); i++) {
        ll c = cols[u][i];
        th[i] = last[c];
        th2[i] = comp_col[c];
        comp_col[c] = (last[c] == par ? comp_col[c] : timer++);
        comps[u][i] = comp_col[c];
        last[c] = u;
    }
    for (ll v : adj[u]) {
        if (v == par) continue;
        dfs1(v, u);
    }
    for (ll i = 0; i < cols[u].size(); i++) {
        ll c = cols[u][i];
        last[c] = th[i];
        comp_col[c] = th2[i];
    }
}

void tc () {
    ll n, k, s, q;
    cin >> n >> k >> s >> q;
    fill(adj, adj+n, vll({}));
    for (ll i = 1; i < n; i++) {
        ll u, v;
        cin >> u >> v;
        u--; v--;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    timer = 1;
    cur = 1;
    fill(cols, cols+n, vll({}));
    fill(comps, comps+n, vll({}));
    fill(comp_col, comp_col+k, -16);
    fill(last, last+k, -16);
    for (ll i = 0; i < s; i++) {
        ll x, c;
        cin >> x >> c;
        x--; c--;
        cols[x].push_back(c);
    }
    dfs1(0, 0);
    for (ll u = 0; u < n; u++) {
        sort(comps[u].begin(), comps[u].end());
    }
    for (ll u = 0; u < n; u++) {
        if (cols[u].size() < B) continue;
        // >= B
        for (ll c : comps[u]) active[c] = true;
        for (ll v = 0; v < n; v++) {
            preProc[cur][v] = 0;
            for (ll c : comps[v]) {
                preProc[cur][v] += active[c];
            }
        }
        for (ll c : comps[u]) active[c] = false;
        curMap[u] = cur++;
    }
    while (q--) {
        ll u, v;
        cin >> u >> v;
        u--; v--;
        if (cols[u].size() >= B) {
            cout << preProc[curMap[u]][v] << ' ';
            continue;
        }
        if (cols[v].size() >= B) {
            cout << preProc[curMap[v]][u] << ' ';
            continue;
        }
        ll ans = 0;
        ll p1 = 0;
        for (ll p2 = 0; p2 < comps[v].size(); p2++) {
            while (p1 < comps[u].size() && comps[u][p1] < comps[v][p2]) p1++;
            if (p1 == comps[u].size() || comps[u][p1] != comps[v][p2]) continue;
            ans++;
        }
        cout << ans << ' ';
    }
    cout << '\n';
}

int main () {
    cin.tie(nullptr) -> sync_with_stdio(false);
    ll T; cin >> T; while (T--) { tc(); }
    return 0;
}
